def fake_search(query):
    facts = {
        "eiffel tower height": "The Eiffel Tower is 330 meters tall.",
        "paris population": "Paris has a population of about 2.1 million.",
    }
    return next((v for k, v in facts.items() if k in query.lower()), "No info found.")

def react_loop(task, max_steps=4):
    trace = []
    for step in range(1, max_steps + 1):
        if step == 1:
            thought = f"I need to find facts about: {task}"
            action = "search"
            action_input = task
        elif step == 2:
            thought = "I have the first fact. Now I should check population."
            action = "search"
            action_input = "paris population"
        else:
            thought = "I have enough information to answer."
            action = "finish"
            action_input = None

        trace.append(f"Thought {step}: {thought}")
        if action == "finish":
            trace.append(f"Action {step}: finish")
            break
        obs = fake_search(action_input)
        trace.append(f"Action {step}: {action}({action_input!r})")
        trace.append(f"Obs {step}: {obs}")
    return trace

for line in react_loop("eiffel tower height"):
    print(line)
